export function codexInvocationBudget(databasePath=path.resolve(process.env.WOORI_AGENT_DB_PATH??'data/woori-agent.sqlite'),now=new Date(),dailyLimit=1){if(!fs.existsSync(databasePath))return{date:now.toISOString().slice(0,10),used:0,limit:dailyLimit,remaining:dailyLimit,subscriptionQuota:'Unknown' as const,available:false,reason:'No persisted invocation ledger is available; execution stays blocked.'};const db=new Database(databasePath,{readonly:true,fileMustExist:true});try{const exists=db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='codex_invocations'").get();if(!exists)return{date:now.toISOString().slice(0,10),used:0,limit:dailyLimit,remaining:dailyLimit,subscriptionQuota:'Unknown' as const,available:false,reason:'Invocation ledger is not initialized.'};const row=db.prepare("SELECT COUNT(*) AS used,SUM(CASE WHEN subscription_usage_status='Unknown' THEN 1 ELSE 0 END) AS unknown FROM codex_invocations WHERE substr(created_at,1,10)=? AND execution_status!='Not Started'").get(now.toISOString().slice(0,10)) as {used:number;unknown:number|null};const remaining=Math.max(0,dailyLimit-row.used);return{date:now.toISOString().slice(0,10),used:row.used,limit:dailyLimit,remaining,subscriptionQuota:'Unknown' as const,available:remaining>0,unknownInvocations:row.unknown??0,reason:remaining?'A local invocation slot remains; ChatGPT subscription balance is still Unknown.':'Persisted local daily invocation limit is exhausted.'};}finally{db.close();}}
